import {waterSource,waterFamilies} from './water-shares-content.mjs';
import {waterView,viewWater,valuesWater,assessWater,waterReply,waterReady,validWaterCheck,validWaterKeep,validWaterAnswer,validWaterSkip,startWater,resumeWater,editWater,supportWater,checkWater,answerWater,skipWater,keepWater,removeWater} from './water-shares-core.mjs';
import {hearButton,stopSpeech} from './play-media.mjs';

const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(attrs,text,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(text)}</button>`;
const amount=units=>units===null||units===undefined?'not entered':units%2?`${units===1?'':Math.floor(units/2)}½`:String(units/2);
const spokenAmount=units=>units===null||units===undefined?'not entered':units%2?units===1?'one half':`${Math.floor(units/2)} and one half`:String(units/2);
const sayHalves=text=>String(text??'').replace(/(\d+)½/g,'$1 and one half').replace(/½/g,'one half');
const pages={meet:'Meet the water',build:'Build a diagram',reader:'A reader’s question',kept:'Kept diagrams'};
const palette=['#357c91','#d0a950','#775c98','#568166','#b15e45'];
const rowColor=(v,index)=>v.rows[index]?.id==='fresh'?'#d0a950':v.rows[index]?.id==='saline'?'#357c91':palette[(index+2)%palette.length];
const records=(items,valid)=>Array.isArray(items)?items.filter(x=>valid(x)):[];
const context=w=>w.page==='reader'?w.source.question.id:w.view;
const hasHelp=(w,kind)=>(w.help?.concept??[]).concat(w.help?.reading??[]).some(x=>x.forId===context(w)&&x.kind===kind);
const visitLabel=x=>`${x.cups===undefined?'':`${x.cups} model cups · `}${x.title}${x.revisitOf?` · revisit of ${x.revisitOf}`:''} · ${x.id}`;
function historyCount(raw,readable,kind){const label=kind==='checks'?'check records':'diagram records';if(!Array.isArray(raw))return `<p class="water-evidence" data-water-history-count="${kind}">The earlier ${label} cannot be counted or read here. Their exact saved form stays in your notebook download.</p>`;const unreadable=raw.length-readable.length;return `<p class="water-evidence" data-water-history-count="${kind}">${readable.length} readable of ${raw.length} retained ${label} · activity limit 16.${unreadable?` ${unreadable} unreadable ${unreadable===1?'record stays':'records stay'} exact in your notebook download and still count toward this limit.`:''}</p>`;}

// Original cup silhouettes, split into two equal model half-cup units.
function cupGrid(s,v){const count=v.totalHalf/2;if(!Number.isInteger(count)||count>200)return `<p>${esc(v.description)}</p>`;const bounds=v.rows.map((r,i)=>v.rows.slice(0,i+1).reduce((n,x)=>n+x.units,0));const colorAt=n=>rowColor(v,Math.max(0,bounds.findIndex(b=>n<b)));return `<figure class="water-cups"><div class="water-trays">${Array.from({length:Math.ceil(count/100)},(_,tray)=>`<svg viewBox="0 0 200 180" role="img" aria-label="${esc(`${v.label}: model tray ${tray+1}, ${Math.min(100,count-tray*100)} cups. Whole-model totals across all trays: ${v.rows.map(r=>`${spokenAmount(r.units)} ${r.label}`).join('; ')}. ${v.whole}`)}"><rect x="1" y="1" width="198" height="178" rx="10" fill="#f5eedb" stroke="#b2baa9"/>${Array.from({length:Math.min(100,count-tray*100)},(_,i)=>{const n=tray*100+i,x=6+(i%10)*19,y=6+Math.floor(i/10)*17;return `<g transform="translate(${x} ${y})"><path d="M1 1H8V14H3Z" fill="${colorAt(n*2)}"/><path d="M8 1H15L13 14H8Z" fill="${colorAt(n*2+1)}"/><path d="M1 1H15L13 14H3Z" fill="none" stroke="#294c4b" stroke-width=".8"/></g>`;}).join('')}</svg>`).join('')}</div><figcaption>${esc(v.whole)}. ${esc(s.copy.zoom)}</figcaption></figure>`;}

function cutaway(){return `<svg class="water-cutaway" viewBox="0 0 440 235" role="img" aria-label="Cutaway: soil moisture above the water table is counted in Other. Below the water table, spaces in soil and rock are filled with groundwater; this is the saturated zone. Ground ice and permafrost are counted in Other separately."><path d="M10 65Q80 35 165 62T330 55L430 64V222H10Z" fill="#e7cca5"/><path d="M10 134H430V222H10Z" fill="#99c6cb"/><path d="M10 134H430" stroke="#235968" stroke-width="3" stroke-dasharray="8 4"/><path d="m22 59 3-14m4 13 5-9m68-4 2-15m4 16 7-7" stroke="#568166" stroke-width="3"/><g fill="#8c7861">${[30,90,170,250,330,400].map((x,i)=>`<ellipse cx="${x}" cy="${161+i%2*25}" rx="12" ry="8"/><ellipse cx="${x+15}" cy="206" rx="9" ry="6"/>`).join('')}</g><g fill="#478caa"><circle cx="55" cy="91" r="4"/><circle cx="83" cy="112" r="3"/><circle cx="118" cy="88" r="4"/></g><g font-family="system-ui,sans-serif" font-size="13" fill="#183f39"><rect x="144" y="76" width="279" height="38" rx="4" fill="#fffdf4"/><text x="151" y="92">Soil moisture · above the water table</text><text x="151" y="107">Counted in Other, separately</text><rect x="228" y="120" width="195" height="23" rx="3" fill="#fffdf4"/><text x="235" y="136">Water table</text><rect x="53" y="158" width="333" height="39" rx="4" fill="#fffdf4"/><text x="60" y="174">Groundwater · saturated zone below the line</text><text x="60" y="189">Water fills spaces in soil and rock</text><text x="12" y="23">A model cutaway · not an underground lake</text></g></svg>`;}
function reservoirArt(id){if(id==='ground')return cutaway();if(id==='ice')return `<svg class="water-small-art" viewBox="0 0 240 110" aria-hidden="true"><path d="M5 100 77 15l34 40 33-45 91 90Z" fill="#9dc4cd" stroke="#356274" stroke-width="2"/><path d="m77 15-36 43 24-9 13 13 17-21 16 14-9-16Z" fill="#fffdf4"/><path d="m144 10-28 42 27-12 21 22 18-6Z" fill="#fffdf4"/><path d="M118 48 98 102h49l-3-62" fill="#d6eaf0" stroke="#356274"/></svg>`;if(id==='saline')return `<svg class="water-small-art" viewBox="0 0 240 110" aria-hidden="true"><circle cx="193" cy="29" r="17" fill="#d0a950"/><path d="M0 58Q30 35 60 58T120 58T180 58T240 58V110H0Z" fill="#357c91"/><path d="M0 80Q30 57 60 80T120 80T180 80T240 80" fill="none" stroke="#d4e9e8" stroke-width="4"/></svg>`;if(id!=='other')return '';return `<svg class="water-small-art" viewBox="0 0 240 110" role="img" aria-label="Several smaller freshwater stores, including ground ice, soil moisture, air, lakes, rivers, wetlands and living things"><path d="M4 98Q65 40 130 80T236 90" fill="none" stroke="#568166" stroke-width="13"/><path d="M108 71Q56 80 114 103" fill="none" stroke="#357c91" stroke-width="10"/><path d="m23 64 7-15 8 15m-8-15v39m175-23V36m0 13q-20-16-19 1 8 13 19 7m0-13q19-20 20-2-3 12-20 12" stroke="#568166" fill="none" stroke-width="4"/><path d="M90 22q0-15 15-10 15-20 27 0 24-2 18 13Z" fill="#cfdee1"/><path d="m158 88 8-15 9 15-9 8Z" fill="#c5dfea" stroke="#356274"/></svg>`;}
function reservoirCards(w){return `<div class="water-reservoirs">${w.source.cards.map(c=>`<article><button type="button" class="water-card" data-water-help="card-${esc(c.id)}" aria-expanded="${hasHelp(w,`card-${c.id}`)}"><span class="water-card-mark" aria-hidden="true">${c.id==='saline'?'≈':c.id==='ice'?'△':c.id==='ground'?'≋':'⋮'}</span><strong>${esc(c.title)}</strong><span>Open this reservoir card</span></button>${hasHelp(w,`card-${c.id}`)?`<div class="water-card-copy">${reservoirArt(c.id)}<p>${esc(c.text)}</p><p class="water-picture-caption">${esc(c.pictureDescription)}</p></div>`:''}</article>`).join('')}</div>`;}
function sourcePanel(w){const s=w.source,v=viewWater(s,w.view);return `<aside class="water-source" aria-label="Frozen source tables"><h2>The water on this visit</h2><p class="water-tag">${esc(s.cups)} model cups · this visitor’s tables</p><p>${esc(s.copy.model)}</p><details class="water-source-details" data-water-panel="source" open><summary>Source tables · both wholes</summary>${s.views.map(table=>`<section class="water-table-block"><h3>${esc(table.label)}</h3><p class="water-view-description">${esc(table.description)}</p><p class="water-table-whole">${esc(table.whole)}</p><table><caption>Source amounts in model cups</caption><thead><tr><th scope="col">Water store</th><th scope="col">Cups</th></tr></thead><tbody>${table.rows.map((r,i)=>`<tr><th scope="row"><span class="water-key" style="--water-color:${rowColor(table,i)}" aria-hidden="true"></span>${esc(r.label)}<details data-water-panel="row-${esc(table.id)}-${esc(r.id)}" class="water-row-detail"><summary>About this store</summary><p>${esc(r.detail)}</p></details></th><td>${esc(amount(r.units))}</td></tr>`).join('')}<tr class="water-table-total"><th scope="row">This whole</th><td>${esc(amount(table.totalHalf))}</td></tr></tbody></table></section>`).join('')}<p class="water-zoom-note">${esc(s.copy.zoom)}</p></details><details data-water-panel="picture" class="water-picture-details"><summary>Picture this whole in cups</summary>${cupGrid(s,v)}<ul class="water-legend">${v.rows.map((r,i)=>`<li><span class="water-key" style="--water-color:${rowColor(v,i)}" aria-hidden="true"></span>${esc(r.label)}: ${esc(amount(r.units))} cups</li>`).join('')}</ul></details><details data-water-panel="reservoirs" class="water-source-reservoirs"><summary>Reservoir cards</summary>${reservoirCards(w)}</details><div class="water-reader-request"><h3>The visitor asks</h3><p><strong>${esc(s.question.prompt)}</strong></p><p>Requested diagram: <strong>${esc(viewWater(s,s.question.view)?.label??s.question.view)}</strong>.</p><p>${esc(s.question.context)}</p></div>${hearButton(sayHalves(`${s.views.map(t=>`${t.whole}. ${t.rows.map(r=>`${r.label}, ${spokenAmount(r.units)} model cups`).join('. ')}`).join('. ')}. The visitor asks: ${s.question.prompt}. ${s.question.context}`),'Hear the tables and request')}</aside>`;}
function help(w){const q=w.source.question,s=w.source,items=[['hint','A hint',q.hint],['example','Different example',q.example],['together','Work together',q.together],['half','What is half a cup?',s.copy.half],...(s.copy.percent?[['percent','What does % mean?',s.copy.percent]]:[]),['zoom','Why does the whole change?',s.copy.zoom],['meaning','Water words',s.copy.limit]];return `<section class="water-help" aria-label="Optional support"><h3>Tools for thinking</h3><div class="water-actions">${items.map(([kind,label])=>btn(`data-water-help="${kind}"`,label)).join('')}</div>${items.filter(([kind])=>hasHelp(w,kind)).map(([kind,label,text])=>`<aside class="water-help-shown" data-water-help-shown="${kind}"><h4>${esc(label)}</h4>${kind==='half'?'<svg viewBox="0 0 130 72" class="water-half-art" role="img" aria-label="One model cup divided into two equal halves"><path d="M20 5h45v60H29Z" fill="#357c91"/><path d="M65 5h45l-9 60H65Z" fill="#d0a950"/><path d="M20 5h90l-9 60H29Z M65 5v60" fill="none" stroke="#183f39" stroke-width="3"/></svg>':''}<p>${esc(text)}</p>${kind==='together'?'<p>This turn records working together.</p>':''}</aside>`).join('')}</section>`;}
function meet(w){const s=w.source;return `<h2 id="water-heading" tabindex="-1">Meet the water</h2><p class="water-story">${esc(s.copy.welcome)}</p><p>Open <strong>Reservoir cards</strong> beside the source tables to meet the water stores. These cards stay available while you build or answer.</p>${btn('data-water-help="teach"','Walk through a source table')}${hasHelp(w,'teach')?`<aside class="water-help-shown"><h3>Whole, rows, then bars</h3><ol><li>Read the whole: ${esc(viewWater(s,w.view).whole)}.</li><li>Read each source row: ${viewWater(s,w.view).rows.map(r=>`${esc(r.label)}, ${esc(amount(r.units))} cups`).join('; ')}.</li><li>Set each bar to its row’s amount. All rows together make this one whole.</li></ol><p>${esc(s.copy.help)}</p></aside>`:''}${help(w)}<div class="water-actions">${btn('data-water-page="build"','Build a diagram',true)}${btn('data-water-page="reader"','Try the reader’s question')}</div>`;}
function graph(s,viewId,values,{saved=false,level=3}={}){const v=viewWater(s,viewId);return `<div class="water-graph${saved?' water-saved-graph':''}" data-water-graph><h${level}>${saved?'Kept diagram':'Your working diagram'} · ${esc(v.label)}</h${level}><p>${esc(v.whole)}</p><p class="water-axis-label">Scale in model cups · every bar starts at 0</p><div class="water-axis" aria-hidden="true"><span>0</span><span>${v.totalHalf%2?'':esc(amount(v.totalHalf/2))}</span><span>${esc(amount(v.totalHalf))}</span></div>${v.rows.map((r,i)=>{const n=values[r.id]??null;return `<div class="water-bar-row"><div class="water-bar-label"><strong>${esc(r.label)}</strong><span data-water-print="${esc(r.id)}">${esc(amount(n))}${n===null?'':' cups'}</span></div><div class="water-bar-track" aria-hidden="true"><span data-water-bar="${esc(r.id)}" data-units="${n??''}" style="--water-color:${rowColor(v,i)};width:${n===null?0:Math.max(0,Math.min(100,n/v.totalHalf*100))}%"></span></div></div>`;}).join('')}<p class="water-graph-caption">Printed values and labels carry the amounts, including bars too small to see.</p></div>`;}
function draftLine(w){const a=assessWater(w.source,w.view,valuesWater(w)),v=viewWater(w.source,w.view);return a.missing.length?`${amount(a.sumHalf)} model cups entered so far; ${a.missing.length} ${a.missing.length===1?'quantity is':'quantities are'} still waiting. This whole is ${amount(v.totalHalf)} cups.`:`Draft total: ${amount(a.sumHalf)} of ${amount(v.totalHalf)} model cups. ${a.sumHalf===v.totalHalf?'The draft total fits this whole.':'The draft total differs from this whole.'}`;}
const readiness=w=>waterReady(w)?'Ready to Keep · this view, its bars and the latest reply fit this visitor. Keep again to save that result.':'Keep any discovery. To fulfill this visitor, keep the requested view with source-matching bars and a fitting latest reply.';
function supportNote(r){const h=r.helpBefore,table=r.tableAvailable===true?'The source table was available.':r.tableAvailable===false?'This result records that the source table was not available.':'Source-table availability was not recorded for this earlier result.';if(!h)return `Earlier support was not observed in this saved result. ${table}`;const id=r.itemId??r.view,concept=(h.concept??[]).filter(x=>x.forId===id).map(x=>x.kind),reading=(h.reading??[]).filter(x=>x.forId===id).map(x=>x.kind);return `${h.observed===true?'Before this result for this turn:':'Earlier support was unobserved. Known requests before this result for this turn:'} concept requests ${concept.length?concept.join(', '):'none recorded'}; reading requests ${reading.length?reading.join(', '):'none recorded'}. ${table}`;}
function diagnosticRows(r){const v=viewWater(r.source,r.view),ids=r.outcome==='missing'?r.missing:r.outcome==='rows'?r.wrongRows:[];return ids.length?`<p>${r.outcome==='missing'?'Still waiting':'Compare these rows'}: ${ids.map(id=>esc(v.rows.find(row=>row.id===id)?.label??id)).join('; ')}.</p>`:'';}
function checkRecord(r,index,level=3){const v=viewWater(r.source,r.view);return `<article class="water-saved-check"><h${level}>Check ${index+1} · ${esc(v.label)}</h${level}><p>${esc(r.feedback)}</p>${diagnosticRows(r)}<p>Recorded draft: ${v.rows.map(row=>`${esc(row.label)}: ${esc(amount(r.values[row.id]))}`).join('; ')}. ${r.missing.length?'Entered so far':'Total'}: ${esc(amount(r.sumHalf))} cups.</p><details><summary>Support and table availability</summary><p class="water-evidence">${esc(supportNote(r))}</p></details></article>`;}
function builder(w){const s=w.source,v=viewWater(s,w.view),vals=valuesWater(w),checks=records(w.checks,validWaterCheck);return `<h2 id="water-heading" tabindex="-1">Build a diagram</h2><p>Read the source table beside you. Set each labeled bar in model cups; a blank is still waiting, while 0 is an entered amount.</p>${graph(s,w.view,vals)}<p class="water-draft-sum" data-water-sum role="status">${esc(draftLine(w))}</p><div class="water-quantity-editor">${v.rows.map((row,i)=>`<fieldset><legend><span class="water-key" style="--water-color:${rowColor(v,i)}" aria-hidden="true"></span>${esc(row.label)}</legend><label for="water-quantity-${i}">Your amount in model cups</label><input id="water-quantity-${i}" data-water-quantity="${esc(row.id)}" type="number" min="0" max="${v.totalHalf/2}" step="0.5" inputmode="decimal" autocomplete="off" value="${vals[row.id]===null||vals[row.id]===undefined?'':vals[row.id]/2}" aria-describedby="water-quantity-note-${i}"><p class="water-input-note" id="water-quantity-note-${i}">0 to ${esc(amount(v.totalHalf))}, including half cups. Source: ${esc(amount(row.units))} cups.</p><div class="water-steps" role="group" aria-label="${esc(`Adjust ${row.label}`)}">${[-20,-2,-1,1,2,20].map(delta=>btn(`data-water-step-row="${esc(row.id)}" data-water-step="${delta}" aria-label="${esc(`${delta<0?'Remove':'Add'} ${spokenAmount(Math.abs(delta))} model cups for ${row.label}`)}"`,`${delta<0?'−':'+'}${amount(Math.abs(delta))}`)).join('')}</div></fieldset>`).join('')}</div><div class="water-actions">${btn('data-water-help="one"','Show one bar')}${btn('data-water-help="fill"','Fill from the table')}${btn('data-water-clear','Clear this view')}</div><p class="water-evidence">Showing or filling bars records support before their values appear.</p><div class="water-actions">${btn('data-water-check','Check this view',true)}${btn('data-water-keep','Keep this diagram')}</div><p class="water-readiness" data-water-ready>${esc(readiness(w))}</p>${checks.length||!Array.isArray(w.checks)||w.checks.length?`<details data-water-panel="checks" class="water-history"><summary>Earlier checks · original records</summary>${historyCount(w.checks,checks,'checks')}${checks.map((r,i)=>checkRecord(r,i)).join('')}</details>${checks.length?`<div class="water-feedback" data-water-outcome="${esc(checks.at(-1).outcome)}"><h3>Latest readable saved check</h3><p>${esc(checks.at(-1).feedback)}</p>${diagnosticRows(checks.at(-1))}<p class="water-evidence">This is the earlier checked draft; edits leave it unchanged.</p></div>`:''}`:''}${help(w)}`;}
function savedAnswer(r,label,level=3){const q=r.source.question;return `<article class="water-saved-answer"><h${level}>${esc(label)}</h${level}><p>${esc(q.prompt)}</p><p>Choice: <strong>${esc(q.choices.find(c=>c.id===r.choice)?.text??r.choice)}</strong></p><p>${esc(r.feedback)}</p><details><summary>Original whole, context and ordered choices</summary><p>${esc(viewWater(r.source,q.view).whole)}</p><p>${esc(q.context)}</p><ol>${q.choices.map(c=>`<li>${esc(c.text)}</li>`).join('')}</ol></details><details><summary>Support and table availability</summary><p class="water-evidence">${esc(supportNote(r))}</p></details></article>`;}
function answerHistory(w,level=3){const raw=w.answer;if(raw===undefined)return '';if(!raw||typeof raw!=='object'||Array.isArray(raw))return '<p>An unreadable earlier response stays exact in the notebook download.</p>';const first=validWaterAnswer(raw.first)?raw.first:null,latest=validWaterAnswer(raw.latest)?raw.latest:null,skip=validWaterSkip(raw.skipped)?raw.skipped:null,same=r=>JSON.stringify(r.source)===JSON.stringify(w.source),retained=(r,key)=>same(r)?'':`<p class="water-evidence" data-water-retained-response="${key}">This retained ${key==='skipped'?'skip':'response'} belongs to another frozen source. It is shown with its original request and does not answer this visit’s current request.</p>`,bad=['first','latest','skipped'].filter(key=>Object.hasOwn(raw,key)&&!(key==='skipped'?validWaterSkip(raw[key]):validWaterAnswer(raw[key])));return `${first?retained(first,'first')+savedAnswer(first,same(first)?'First supplied response · kept as answered':'Retained first response · another frozen source',level):''}${latest&&JSON.stringify(first)!==JSON.stringify(latest)?retained(latest,'latest')+savedAnswer(latest,same(latest)?'Latest supplied response':'Retained latest response · another frozen source',level):''}${skip?`${retained(skip,'skipped')}<p class="water-evidence">A skip was recorded. ${esc(supportNote(skip))} Answered first and latest responses stay in place.</p>${same(skip)?'':`<details><summary>Original skipped request</summary><p>${esc(skip.source.question.prompt)}</p></details>`}`:''}${bad.length?`<p class="water-evidence" data-water-retained-response="unreadable">Unreadable ${bad.map(esc).join(', ')} response records stay exact in your notebook download.</p>`:''}`;}
function reader(w){const q=w.source.question,latest=waterReply(w);return `<h2 id="water-heading" tabindex="-1">A reader’s question</h2><p>The source tables stay available. You can answer before or after building, change your reply, or skip.</p><section class="water-question"><p>${esc(q.context)}</p><h3 id="water-question-heading" tabindex="-1">${esc(q.prompt)}</h3><div class="water-answers" role="group" aria-label="Supplied reader answers">${q.choices.map(c=>btn(`data-water-answer="${esc(c.id)}" aria-pressed="${latest?.choice===c.id}"`,c.text)).join('')}</div>${btn('data-water-skip','Skip this question')}${hearButton(sayHalves(`${q.context} ${q.prompt} ${q.choices.map(c=>c.text).join('. ')}`),'Hear question and choices')}</section>${answerHistory(w)}<p class="water-readiness" data-water-ready>${esc(readiness(w))}</p><div class="water-actions">${btn('data-water-page="build"','Back to your diagram')}${btn('data-water-keep','Keep this diagram')}</div>${help(w)}<aside class="water-talk"><h3>Talk together, if you like</h3><p>How could your diagram help the reader? Say or show your idea off screen. Nothing is recorded from your explanation.</p></aside>`;}
function keptRecord(r,i,level=3){const v=viewWater(r.source,r.view);return `<article class="water-kept-diagram"><h${level}>Diagram ${i+1} · ${esc(v.label)}</h${level}><p class="water-kept-result">${r.fulfilled===true?'This visitor can read your diagram · fulfilled when kept.':'A discovery kept for another look · visitor not fulfilled when kept.'}</p>${graph(r.source,r.view,r.values,{saved:true,level:level+1})}<p>${esc(r.feedback)}</p><details><summary>Support and table availability</summary><p class="water-evidence">${esc(supportNote(r))}</p></details><p class="water-evidence">Later edits or answers do not change this result.</p>${validWaterAnswer(r.answer)?savedAnswer(r.answer,'Reply frozen with this diagram',level+1):'<p>No readable supplied reply was used for this kept diagram.</p>'}<details><summary>Original source and request</summary><p>${esc(r.source.question.prompt)}</p><p>${esc(r.source.question.context)}</p>${r.source.views.map(table=>`<p><strong>${esc(table.whole)}</strong>: ${table.rows.map(row=>`${esc(row.label)} ${esc(amount(row.units))}`).join('; ')} model cups.</p>`).join('')}</details></article>`;}
function kept(w,notes=false){const rows=records(w.kept,validWaterKeep),checks=records(w.checks,validWaterCheck),level=notes?4:2;return `<h${level}${notes?'':' id="water-heading" tabindex="-1"'}>Kept diagrams</h${level}><p>A kept diagram freezes its own bars, whole, reader reply, support and original result. A later fitting answer needs another Keep.</p>${historyCount(w.kept,rows,'keeps')}${rows.length?rows.map((r,i)=>keptRecord(r,i,level+1)).join(''):'<p>No readable diagrams kept yet. An unfinished or different diagram can be a useful discovery too.</p>'}<details data-water-panel="answers"><summary>Reader responses · first and latest</summary>${answerHistory(w,level+1)||'<p>No supplied responses yet.</p>'}</details>${notes?`<details><summary>Saved checks</summary>${historyCount(w.checks,checks,'checks')}${checks.map((r,i)=>checkRecord(r,i,level+1)).join('')||'<p>No readable saved checks.</p>'}</details>`:''}`;}
function chooser(w){return `<details class="water-chooser" data-water-panel="chooser"><summary>Choose another visitor · 16 open settings</summary><p>A new visit freezes its request and tables, keeping earlier visits. The eight families each have a 100 or 200 cup model. The next-visitor button cycles this finite set; repeats are revisits.</p><label>Visitor question<select data-water-family>${waterFamilies.map(f=>`<option value="${esc(f.id)}" ${w?.source.family===f.id?'selected':''}>${esc(f.label)}</option>`).join('')}</select></label><label>Size of each model whole<select data-water-cups><option value="100" ${w?.source.cups===100?'selected':''}>100 model cups · one tray</option><option value="200" ${w?.source.cups===200?'selected':''}>200 model cups · two trays</option></select></label><div class="water-actions">${btn('data-water-chosen-start','Start this visitor',true)}${btn('data-water-start','Next visitor in the cycle')}</div></details>`;}
function grownup(s){return `<details class="water-grownups" data-water-panel="grownups"><summary>Grown-ups · model, sources and limits</summary><p>${esc(s.copy.sources)}</p><p>${esc(s.copy.limit)}</p><p>${esc(s.copy.support)}</p><p>The model describes stored shares, not rainfall, annual flow, accessible supply or household water. Equal-size pictures with different water wholes do not mean equal real quantities.</p><ul>${s.sources.map(x=>`<li><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.label)}</a></li>`).join('')}</ul><p>Original fiction, wording and diagrams. This activity does not record spoken explanations.</p></details>`;}
export function waterEntry(){return '<aside class="water-entry"><h2>Hundred Cups</h2><p>Two water wholes, one reader. Build a labeled diagram and see what changes when you zoom into freshwater.</p><a class="secondary" href="#science/water-shares">Visit Hundred Cups</a></aside>';}
export function waterPage(state){const v=waterView(state),w=v.work,s=w?.source??waterSource,head='<section class="water-shares" data-water-root><header class="water-header"><a class="back" href="#science/water">Back to the Water Lab</a><p class="water-eyebrow">After the storm · a model table</p><h1>Hundred Cups</h1><p class="water-subtitle">Name the whole. Make the shares visible.</p></header>';if(v.status==='unavailable')return head+'<section class="water-turn"><h2 id="water-heading" tabindex="-1">Earlier water work is retained</h2><p>This version cannot edit that saved format. Its exact form remains in your notebook download. Other destinations stay open.</p><a class="secondary" href="#notes">Open notes</a></section></section>';
 const visits=v.visits.length?`<details class="water-visits" data-water-panel="visits"><summary>Your water visits (${v.visits.length})</summary><div class="water-actions">${v.visits.map(x=>x.readable?btn(`data-water-resume="${esc(x.id)}" aria-pressed="${v.root?.current===x.id}"`,visitLabel(x)):'<p>An unreadable visit is retained in your notebook download.</p>').join('')}</div></details>`:'';
 if(!w)return head+`<section class="water-welcome"><div><h2 id="water-heading" tabindex="-1">A whole world in a model tray</h2><p class="water-story">${esc(s.copy.welcome)}</p><p>Choose 100 or 200 model cups. Every destination and all three turns are open.</p><div class="water-actions">${btn('data-water-start','Meet the next visitor',true)}</div>${chooser(null)}</div><div>${cupGrid(s,s.views[0])}</div></section>${visits}${grownup(s)}<p id="water-status" role="status" tabindex="-1"></p></section>`;
 const repeated=v.visits.some(x=>x.readable&&x.id!==v.root.current&&v.root.visits[x.id].source.id===s.id),current=viewWater(s,w.view);return head+`
${repeated?'<p class="water-revisit" data-water-revisit>Back again! You have kept this request and model before. Try a different diagram, or compare your earlier work.</p>':''}<div class="water-whole-banner" data-water-whole><span>Current displayed whole</span><strong>${esc(current.whole)}</strong><p>${esc(s.copy.zoom)}</p></div><nav class="water-pages" aria-label="Hundred Cups turns">${Object.entries(pages).map(([key,label])=>btn(`data-water-page="${key}" aria-current="${w.page===key?'step':'false'}"`,label)).join('')}</nav><div class="water-view-picker" role="group" aria-label="Choose the diagram whole">${s.views.map(table=>btn(`data-water-view="${esc(table.id)}" aria-pressed="${w.view===table.id}"`,table.label)).join('')}<p>Switching views preserves both working diagrams. These are different water sets, each redrawn with ${esc(s.cups)} model cups.</p></div><div class="water-work">${sourcePanel(w)}<section class="water-turn">${w.page==='meet'?meet(w):w.page==='build'?builder(w):w.page==='reader'?reader(w):kept(w)}</section></div><p id="water-status" role="status" tabindex="-1"></p><div data-water-pending-actions hidden><p>Your typed quantity is still visible and has not been saved. Correct it to continue, or deliberately restore the saved numbers.</p>${btn('data-water-restore','Restore saved numbers')}</div>${chooser(w)}${visits}<details class="water-space" data-water-panel="space"><summary>Notebook download or make space</summary><p>Up to sixteen visits, sixteen checks and sixteen keeps per visit fit the activity limit; the shared notebook may fill sooner. Nothing is automatically removed.</p><a class="secondary" href="#notes">Open notes and download</a><div class="water-actions">${v.visits.filter(x=>x.readable).map(x=>btn(`data-water-delete="${esc(x.id)}"`,`Remove ${visitLabel(x)}`)).join('')}</div></details>${grownup(s)}<footer><a class="secondary" href="#science/water">Water Lab</a><a class="secondary" href="#pathways/science">Other science explorations</a><a class="secondary" href="#numbers/hundredths">Explore equal whole pictures</a></footer></section>`;
}
export function waterNotes(state){if(!Object.hasOwn(state,'waterShares'))return '';const v=waterView(state);return `<details class="panel water-notes"><summary>Hundred Cups · model diagrams and reader responses</summary><p>Frozen model sources and original results. Table access, concept support, reading support and first/latest replies stay distinct. No claim of mastery or practical water safety is made.</p>${v.visits.filter(x=>x.readable).map(x=>`<section><h3>Visit ${esc(visitLabel(x))}</h3>${kept(v.root.visits[x.id],true)}</section>`).join('')}<p>Malformed or future saved entries stay exact in the raw download; readable sibling visits remain open.</p><details><summary>Exact saved sources and work</summary><pre>${esc(JSON.stringify(state.waterShares,null,2))}</pre></details></details>`;}

let removePendingGuards=()=>{},pendingNavigation=()=>false;
export const guardWaterNavigation=()=>pendingNavigation();
export function bindWater(state,{save,render,focus,canExport,explorerId,isActive}={}){
 removePendingGuards();removePendingGuards=()=>{};
 const root=document.querySelector('[data-water-root]');if(!root)return;
 const owner=explorerId?.(),route=location.hash,o={canExport},pending=new Set();
 const live=el=>root.isConnected&&el?.isConnected&&root.contains(el)&&location.hash===route&&explorerId?.()===owner&&(!isActive||isActive());
 const say=text=>{const n=root.querySelector('#water-status');if(n)n.textContent=text;};
 const pendingUI=()=>{const n=root.querySelector('[data-water-pending-actions]');if(n)n.hidden=!pending.size;};
 const pendingMessage='A typed quantity has not been saved. Correct the marked field or choose Restore saved numbers before continuing.';
 const updateDraft=()=>{const w=waterView(state).work;if(!w)return;const v=viewWater(w.source,w.view),values=valuesWater(w);for(const [i,row] of v.rows.entries()){const bar=root.querySelectorAll('[data-water-bar]')[i],print=root.querySelectorAll('[data-water-print]')[i];if(bar){bar.style.width=`${values[row.id]===null?0:values[row.id]/v.totalHalf*100}%`;bar.dataset.units=values[row.id]??'';}if(print)print.textContent=`${amount(values[row.id])}${values[row.id]===null?'':' cups'}`;}const sum=root.querySelector('[data-water-sum]');if(sum)sum.textContent=draftLine(w);root.querySelectorAll('[data-water-ready]').forEach(n=>{n.textContent=readiness(w);});};
 const act=(el,fn,message='',target='#water-heading')=>{if(!live(el))return;if(pending.size){say(pendingMessage);return;}const r=fn();if(!r?.ok){say(r?.error??'This change could not be saved. Earlier work stays in place. Download your notes before making space.');return;}const panels=new Map([...root.querySelectorAll('details[data-water-panel]')].map(n=>[n.dataset.waterPanel,n.open])),scroll=window.scrollY;stopSpeech();save?.();render?.();const next=document.querySelector('[data-water-root]');next?.querySelectorAll('details[data-water-panel]').forEach(n=>{if(panels.has(n.dataset.waterPanel))n.open=panels.get(n.dataset.waterPanel);});const status=next?.querySelector('#water-status');if(status)status.textContent=message;if(target){const node=document.querySelector(target);if(node){node.focus({preventScroll:true});if(target==='#water-heading')focus?.(target);else window.scrollTo({top:scroll,behavior:'instant'});}}};
 const on=(selector,fn)=>root.querySelectorAll(selector).forEach(el=>el.addEventListener('click',()=>{if(live(el))fn(el);}));
 on('[data-water-start]',b=>act(b,()=>startWater(state,o),'A new visitor is open. Earlier work is retained.'));
 on('[data-water-chosen-start]',b=>act(b,()=>startWater(state,{...o,family:root.querySelector('[data-water-family]').value,cups:Number(root.querySelector('[data-water-cups]').value)}),'Your selected visitor is open with frozen tables.'));
 on('[data-water-resume]',b=>act(b,()=>resumeWater(state,b.dataset.waterResume,o),'Resumed the original source and request.'));
 on('[data-water-page]',b=>act(b,()=>editWater(state,'page',b.dataset.waterPage,o)));
 on('[data-water-view]',b=>act(b,()=>editWater(state,'view',b.dataset.waterView,o),'Displayed whole changed. Both working graphs are retained.'));
 root.querySelectorAll('[data-water-quantity]').forEach(input=>input.addEventListener('input',()=>{
  if(!live(input))return;const w=waterView(state).work;if(!w)return;const v=viewWater(w.source,w.view),number=input.value===''?null:Number(input.value),units=number===null?null:number*2,invalid=input.validity.badInput||input.value!==''&&(!Number.isInteger(units)||units<0||units>v.totalHalf);
  if(invalid){pending.add(input);input.setAttribute('aria-invalid','true');say(`Enter 0 to ${amount(v.totalHalf)} model cups in whole or half cups. Your typed quantity is still here.`);pendingUI();return;}
  const r=editWater(state,'bar',{row:input.dataset.waterQuantity,units},o);if(!r?.ok){pending.add(input);input.setAttribute('aria-invalid','true');say(r?.error??'This typed quantity could not be saved. It stays visible; correct it or restore saved numbers before continuing.');pendingUI();return;}
  pending.delete(input);input.removeAttribute('aria-invalid');save?.();updateDraft();pendingUI();say(pending.size?pendingMessage:'Quantity saved.');
 }));
 on('[data-water-step]',b=>act(b,()=>editWater(state,'step',{row:b.dataset.waterStepRow,delta:Number(b.dataset.waterStep)},o),'Quantity saved.',`#${b.closest('fieldset').querySelector('input').id}`));
 on('[data-water-clear]',b=>act(b,()=>editWater(state,'clear',null,o),'This working view is clear.','#water-heading'));
 on('[data-water-check]',b=>act(b,()=>checkWater(state,o),'Check saved with the actual draft.','[data-water-check]'));
 on('[data-water-keep]',b=>act(b,()=>keepWater(state,o),'Diagram kept with its original result and reply.','[data-water-keep]'));
 on('[data-water-answer]',b=>act(b,()=>answerWater(state,b.dataset.waterAnswer,o),'Reply saved. Your first response remains as answered.','#water-question-heading'));
 on('[data-water-skip]',b=>act(b,()=>skipWater(state,o),'Skip recorded. Earlier supplied replies remain as answered.','#water-question-heading'));
 on('[data-water-help]',b=>act(b,()=>supportWater(state,b.dataset.waterHelp,o),'Support request saved before showing it.',`[data-water-help="${b.dataset.waterHelp}"]`));
 on('[data-water-delete]',b=>{if(pending.size){say(pendingMessage);return;}const visit=waterView(state).visits.find(x=>x.id===b.dataset.waterDelete);if(window.confirm(`Remove visit ${visit?visitLabel(visit):b.dataset.waterDelete} and its diagrams, responses and support records? Download notes first if you want to retain them.`))act(b,()=>removeWater(state,b.dataset.waterDelete,true,o),'Selected visit removed.');});
 on('[data-water-restore]',b=>{if(!live(b))return;pending.clear();render?.();focus?.('#water-heading');});
 // Capture commits reading support before the host can start local playback.
 root.addEventListener('click',e=>{const b=e.target.closest?.('[data-speak]');if(!b)return;if(!live(b)||pending.size){e.preventDefault();e.stopImmediatePropagation();if(pending.size)say(pendingMessage);return;}const r=supportWater(state,'audio',o);if(!r?.ok){e.preventDefault();e.stopImmediatePropagation();say(r?.error??'Listening could not be recorded. Your earlier work remains.');return;}save?.();},true);
 // A refused typed edit must not be silently lost through host navigation/explorer controls.
 const guard=e=>{if(e.type==='keydown'&&!['Enter',' '].includes(e.key))return;if(!root.isConnected||location.hash!==route||explorerId?.()!==owner||!pending.size)return;const target=e.target;if(target?.closest?.('[data-water-quantity],[data-water-restore]'))return;if(target?.closest?.('button,a,select,input')){e.preventDefault();e.stopImmediatePropagation();say(pendingMessage);}};
 pendingNavigation=()=>{if(!root.isConnected||explorerId?.()!==owner||!pending.size)return false;history.replaceState(null,'',route);say(pendingMessage);return true;};
 const beforeLeave=e=>{if(pending.size&&root.isConnected){e.preventDefault();e.returnValue='';}};
 document.addEventListener('click',guard,true);document.addEventListener('keydown',guard,true);window.addEventListener('beforeunload',beforeLeave);
 removePendingGuards=()=>{document.removeEventListener('click',guard,true);document.removeEventListener('keydown',guard,true);pendingNavigation=()=>false;window.removeEventListener('beforeunload',beforeLeave);};
}
